CREATE TABLE r2_manual_objects (app TEXT NOT NULL CHECK(app='maintenance'),object_key TEXT NOT NULL CHECK(object_key LIKE 'manuals/rides/%.pdf'),size INTEGER NOT NULL CHECK(size>=20 AND size<=20971520),sha256 TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(app,object_key));
DROP TRIGGER r2_objects_quota;
CREATE TRIGGER r2_objects_quota BEFORE INSERT ON r2_objects WHEN NOT EXISTS(SELECT 1 FROM r2_objects WHERE app=NEW.app AND object_key=NEW.object_key) AND (SELECT COALESCE(SUM(size),0) FROM r2_objects WHERE app=NEW.app)+(SELECT COALESCE(SUM(size),0) FROM r2_manual_objects WHERE app=NEW.app)+NEW.size>4000000000 BEGIN SELECT RAISE(ABORT,'R2_BUDGET_FULL'); END;
CREATE TRIGGER r2_manual_quota BEFORE INSERT ON r2_manual_objects WHEN NOT EXISTS(SELECT 1 FROM r2_manual_objects WHERE app=NEW.app AND object_key=NEW.object_key) AND (SELECT COALESCE(SUM(size),0) FROM r2_objects WHERE app=NEW.app)+(SELECT COALESCE(SUM(size),0) FROM r2_manual_objects WHERE app=NEW.app)+NEW.size>4000000000 BEGIN SELECT RAISE(ABORT,'R2_BUDGET_FULL'); END;
